module TopModule (
    input  logic         clk,
    input  logic         load,
    input  logic [255:0] data,
    output logic [255:0] q
);

    logic [15:0] row_grid [15:0];
    logic [15:0] next_row_grid [15:0];

    // Unpack q into row_grid
    always_comb begin
        for (int r = 0; r < 16; r++) begin
            row_grid[r] = q[r*16 +: 16];
        end
    end

    // Compute next state
    always_comb begin
        for (int r = 0; r < 16; r++) begin
            for (int c = 0; c < 16; c++) begin
                int r_up, r_dn, c_lf, c_rt;
                logic [3:0] count;
                logic curr, nxt;

                r_up = (r == 0) ? 15 : r - 1;
                r_dn = (r == 15) ? 0 : r + 1;
                c_lf = (c == 0) ? 15 : c - 1;
                c_rt = (c == 15) ? 0 : c + 1;

                curr = row_grid[r][c];
                count = row_grid[r_up][c_lf] +
                        row_grid[r_up][c   ] +
                        row_grid[r_up][c_rt] +
                        row_grid[r    ][c_lf] +
                        row_grid[r    ][c_rt] +
                        row_grid[r_dn][c_lf] +
                        row_grid[r_dn][c   ] +
                        row_grid[r_dn][c_rt];

                if (count == 3)
                    nxt = 1'b1;
                else if (count == 2)
                    nxt = curr;
                else
                    nxt = 1'b0;

                next_row_grid[r][c] = nxt;
            end
        end
    end

    // Sequential update
    always_ff @(posedge clk) begin
        if (load) begin
            q <= data;
        end else begin
            for (int r = 0; r < 16; r++) begin
                q[r*16 +: 16] <= next_row_grid[r];
            end
        end
    end

endmodule

